import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Browse Recipes","description":"","frontmatter":{"title":"Browse Recipes"},"headers":[],"relativePath":"docs/getting-started/browse-recipes.md","filePath":"docs/getting-started/browse-recipes.md","lastUpdated":1794508483000}'),o={name:"docs/getting-started/browse-recipes.md"};function s(n,e,c,p,d,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="browse-recipes" tabindex="-1">Browse Recipes <a class="header-anchor" href="#browse-recipes" aria-label="Permalink to &quot;Browse Recipes&quot;">​</a></h1><p><strong>Recipes</strong> are pre-built charts and breakdowns over your project&#39;s data — spending by category, account balances over time, portfolio performance, debt payoff progress, and more. They run the underlying analysis without waiting for a chat answer.</p><h2 id="opening-a-recipe" tabindex="-1">Opening a recipe <a class="header-anchor" href="#opening-a-recipe" aria-label="Permalink to &quot;Opening a recipe&quot;">​</a></h2><p>The Recipes panel sits alongside chat in your project. Pick a recipe from the list to run it and see its chart. Use the available time-period controls to choose the history for a recipe. Some analyses need more records or a complete period; review any message explaining missing history.</p><p>A Standard Workbook offers focus views across its source projects, including combined spending, investments and net worth. Retirement Planning workbooks have their own retirement recipes.</p><h2 id="drilling-into-detail" tabindex="-1">Drilling into detail <a class="header-anchor" href="#drilling-into-detail" aria-label="Permalink to &quot;Drilling into detail&quot;">​</a></h2><p>Click a bar, category, or KPI on a chart to drill in — the tile swaps to a detailed table or breakdown for just that slice, and you can step back out to the overview. If the underlying data changes while a recipe is open (for example, a new source finishes importing), the result dims to show it&#39;s stale rather than disappearing, so you know to re-run it.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Recipes are great for questions you&#39;ll ask often. For anything else — or to dig deeper into a specific number — try <a href="/docs/getting-started/ask-questions">asking questions about your data</a> in chat.</p>',9)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
